-- Repeat-safe additions for the user's primary A/L academic interest.
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='users' AND column_name='academic_level')=0,'ALTER TABLE users ADD COLUMN academic_level VARCHAR(20) NULL AFTER bio','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='users' AND column_name='academic_stream')=0,'ALTER TABLE users ADD COLUMN academic_stream VARCHAR(100) NULL AFTER academic_level','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='users' AND column_name='academic_subject')=0,'ALTER TABLE users ADD COLUMN academic_subject VARCHAR(255) NULL AFTER academic_stream','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
